"""Четыре графика на одной фигуре."""
import numpy as np


def draw(fig):
    x = np.linspace(0, 10, 200)
    axes = fig.subplots(2, 2)
    axes[0, 0].plot(x, np.sin(x))
    axes[0, 0].set_title("sin x")
    axes[0, 1].plot(x, np.exp(-x / 3) * np.cos(2 * x), "r")
    axes[0, 1].set_title("затухание")
    axes[1, 0].step(x[::20], np.sqrt(x[::20]), "g")
    axes[1, 0].set_title("ступени")
    axes[1, 1].fill_between(x, np.sin(x), np.cos(x), alpha=0.5)
    axes[1, 1].set_title("заливка")
    fig.tight_layout()


if __name__ == "__main__":
    from mpldemo import run
    run(draw)
